      "version": ">=12.0.0 <13.0.0",
      "onFail": "download"
    }
  }
}
```

Note

When pnpm 12 is declared via the legacy `packageManager` field and [`pmOnFail`](/settings/cli#pmonfail) is not set to `ignore`, its resolution info is written to `pnpm-lock.yaml`. The lockfile then gains a leading [env lockfile document](/lockfile).

Since v12.0.0-rc.6, the field can also name [another package manager](/package-managers) — `npm`, `yarn` or `bun` — which is what `pnpm add npm@11` writes.

Write a plugin
====================================================

A docsify plugin is a function with the ability to execute custom JavaScript code at various stages of Docsify's lifecycle.

Setup
----------------------------------

Docsify plugins can be added directly to the `plugins` array:

```
window.$docsify = {
  plugins: [
    function myPlugin1(hook, vm) {
      // ...
    },
    function myPlugin2(hook, vm) {
      // ...
    },
  ],
};
```

Alternatively, a plugin can be stored in a separate file and "installed" using a standard `<script>` tag:

```
// docsify-plugin-myplugin.js

{
  function myPlugin(hook, vm) {
    // ...
  }

  // Add plugin to docsify's plugin array
  window.$docsify = window.$docsify || {};
  $docsify.plugins = [...($docsify.plugins || []), myPlugin];

$docsify = {
  plugins: [
    function pageFooter(hook, vm) {
      const footer = /* html */ `
        <hr/>
        <footer>
          <span><a href="https://github.com/QingWei-Li">cinwell</a> ©2017.</span>
          <span>Proudly published with <a href="https://github.com/docsifyjs/docsify" target="_blank">docsify</a>.</span>
        </footer>
      `;

      hook.afterEach(html => {
        return html + footer;
      });
    },
  ],
};
```

